window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-122"]=[{"id":"set2-50oKY2N7","fingerprint":"fefbdc2cdc11c0ec","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Ce definește termenul de dinte supranumerar?","options":[{"id":"A","text":"Un dinte orientat cu coroana spre baza maxilarului și rădăcina spre planul de ocluzie."},{"id":"B","text":"Un dinte situat în interiorul altui dinte."},{"id":"C","text":"Existența unuia sau a mai multor dinți în plus față de formula dentară, erupți sau situați intraosos."},{"id":"D","text":"Un dinte suplimentar situat exclusiv distal de molari."},{"id":"E","text":"Absența congenitală a unui număr de dinți din formula dentară normală."}],"correct":["C"],"pages":[453],"source":"set-2"},{"id":"set2-fi5dyccK","fingerprint":"b4b5dd0ebe36b268","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele afirmații referitoare la frecvența și distribuția dinților supranumerari sunt adevărate?","options":[{"id":"A","text":"Se localizează cu predilecție pe maxilarul superior, în special în zona incisivilor."},{"id":"B","text":"Sunt de două ori mai frecvenți la sexul feminin comparativ cu cel masculin."},{"id":"C","text":"Cel mai frecvent, pacienții prezintă între 4 și 6 dinți supranumerari."},{"id":"D","text":"Apar cu o frecvență mai mare în dentiția permanentă decât în cea temporară, într-un raport de 9/1."},{"id":"E","text":"Frecvența generală a dinților supranumerari în raport cu alte anomalii este de peste 10%."}],"correct":["A","D"],"pages":[453],"source":"set-2"},{"id":"set2-k2yGVrhx","fingerprint":"4c721fe2681893ce","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este termenul specific utilizat pentru un dinte supranumerar situat lângă linia mediană?","options":[{"id":"A","text":"Distomolare"},{"id":"B","text":"Anastrofic"},{"id":"C","text":"Meziodens"},{"id":"D","text":"Paramolare"},{"id":"E","text":"Dens în dente"}],"correct":["C"],"pages":[453],"source":"set-2"},{"id":"set2-B_tQXlwR","fingerprint":"bd35a29ed88cff77","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Ce susține în esență teoria „atavică” în explicarea etiologiei dinților supranumerari?","options":[{"id":"A","text":"O dezvoltare excesivă a lamei dentare care duce la formarea de muguri suplimentari."},{"id":"B","text":"Acțiunea factorilor externi asupra embrionului în zonele odontogene."},{"id":"C","text":"Reîntoarcerea la formule dentare anterioare sau reapariția unor dinți dispăruți în filogeneză."},{"id":"D","text":"O diviziune a unui mugure dentar normal în doi muguri separați."},{"id":"E","text":"O eroare în dezvoltarea ontogenetică fără legătură cu evoluția filogenetică."}],"correct":["C"],"pages":[453],"source":"set-2"},{"id":"set2-1Lf3nfnt","fingerprint":"1768687b330ef300","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele denumiri sunt, de asemenea, utilizate în literatura de specialitate pentru a descrie surplusul dentar?","options":[{"id":"A","text":"Oligodonție"},{"id":"B","text":"Poliodonție"},{"id":"C","text":"Microdonție"},{"id":"D","text":"Pleodonție"},{"id":"E","text":"Hiperodonție"}],"correct":["B","D","E"],"pages":[453],"source":"set-2"},{"id":"set2-4mzCMHfy","fingerprint":"7bdfcdbc27931bfc","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este premisa fundamentală a teoriei atavice în explicarea apariției dinților supranumerari?","options":[{"id":"A","text":"Apariția dinților în plus este cauzată de o mineralizare tardivă și defectuoasă a unor germeni dentari secundari."},{"id":"B","text":"Apariția dinților supranumerari se datorează neatrofierii unor muguri dentari suplimentari generați fiziologic."},{"id":"C","text":"Dinții supranumerari se dezvoltă din resturi epiteliale ale unei dentiții prelacteale."},{"id":"D","text":"Fenomenul reprezintă o reîntoarcere la formule dentare anterioare sau reapariția unor elemente dentare dispărute în cursul filogenezei."},{"id":"E","text":"Dinții supranumerari sunt rezultatul unei a treia perioade de activitate a lamei dentare."}],"correct":["D"],"pages":[454],"source":"set-2"},{"id":"set2-JwwZEwwB","fingerprint":"04c9e5740cf7bc65","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele aspecte reprezintă limite sau probleme nerezolvate ale teoriei atavice?","options":[{"id":"A","text":"Acceptarea aproape unanimă a faptului că meziodensul este un fenomen atavic."},{"id":"B","text":"Prezența dinților supranumerari situați vestibular sau în linia arcadei."},{"id":"C","text":"Coexistența la același individ a dinților supranumerari și a anodonției."},{"id":"D","text":"Frecvența diferită a dinților supranumerari pe cele două arcade dentare."},{"id":"E","text":"Apariția excepțională a caninilor supranumerari."}],"correct":["C","D","E"],"pages":[454],"source":"set-2"},{"id":"set2-ik3qkG3K","fingerprint":"d9958a2e3213ef49","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele afirmații sunt argumente pro sau contra teoriei celei de-a treia dentiții?","options":[{"id":"A","text":"Teoria se bazează pe revenirea la formula dentară a primatelor."},{"id":"B","text":"Prezența dinților supranumerari care însoțesc dentiția temporară este un contraargument pentru această teorie."},{"id":"C","text":"Existența dinților supranumerari cu grad de calcifiere similar celor din seria normală contrazice teoria."},{"id":"D","text":"Teoria explică forma și structura, de multe ori normală, a dinților supranumerari."},{"id":"E","text":"Apariția frecventă a dinților supranumerari în poziție orală față de arcada normală susține teoria."}],"correct":["B","C","E"],"pages":[454],"source":"set-2"},{"id":"set2-mWPF1DkP","fingerprint":"fefe012946f9c519","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Referitor la teoria mugurilor adamantini multipli, care dintre următoarele enunțuri sunt adevărate?","options":[{"id":"A","text":"Dinții supranumerari apar deoarece unii muguri dentari suplimentari, generați fiziologic, nu se atrofiază."},{"id":"B","text":"Studiile au notat existența unor muguri rudimentari ce indică o linie de patru dentiții: prelacteală, lacteală, permanentă și postpermanentă."},{"id":"C","text":"Teoria este susținută de apariția dinților supranumerari cu o mineralizare tardivă și defectuoasă."},{"id":"D","text":"Dinții prelacteali sunt dinți de lapte cu erupție precoce, care se exfoliază în primele săptămâni de viață."},{"id":"E","text":"Forma și structura adesea normală a dinților supranumerari reprezintă un argument în favoarea acestei teorii."}],"correct":["A","B","E"],"pages":[454],"source":"set-2"},{"id":"set2-HcC8CKyl","fingerprint":"33217b8379046982","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Ce caracteristici definesc dinții prelacteali?","options":[{"id":"A","text":"Sunt identici din punct de vedere structural cu dinții de lapte cu erupție precoce."},{"id":"B","text":"Nu au rădăcină și se exfoliază în general în cursul primelor săptămâni de viață."},{"id":"C","text":"Au formă de capușon de gingie și sunt structuri keratinizate."},{"id":"D","text":"Sunt dinți permanenți care s-au dezvoltat cu mult înaintea celorlalți."},{"id":"E","text":"Sunt structuri epiteliale rudimentare, prezente la naștere."}],"correct":["B","C","E"],"pages":[454],"source":"set-2"},{"id":"set2-haYUNzkF","fingerprint":"31ec454748d95ac8","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt caracteristicile dinților prelacteali, conform descrierilor din literatura de specialitate?","options":[{"id":"A","text":"Nu prezintă rădăcină și pot fi îndepărtați cu ușurință."},{"id":"B","text":"Sunt identici din punct de vedere structural cu dinții de lapte cu erupție precoce."},{"id":"C","text":"Sunt structuri keratinizate prezente la naștere."},{"id":"D","text":"Sunt produși de o supraproducție a lamei dentare laterale."},{"id":"E","text":"Se exfoliază, de regulă, în primele săptămâni de viață."}],"correct":["A","C","E"],"pages":[455],"source":"set-2"},{"id":"set2-50qxteME","fingerprint":"b6c5ae60fa3efe05","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele mecanisme sunt propuse pentru a explica teoria hiperactivității lamei dentare în formarea dinților supranumerari?","options":[{"id":"A","text":"Formarea dinților supranumerari pe seama lamei dentare laterale."},{"id":"B","text":"O perturbare histochimică ce influențează activitatea normală a lamei dentare."},{"id":"C","text":"Diviziunea în două părți a unui mugure dentar din seria normală."},{"id":"D","text":"Activarea unei lame epiteliale accesorii, corespunzătoare „bandei glandulare” a reptilelor."},{"id":"E","text":"O inducție vasculară localizată care stimulează lama dentară."}],"correct":["A","B","E"],"pages":[455],"source":"set-2"},{"id":"set2-V6otahtq","fingerprint":"4a458481a25cbdb0","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Ce mecanisme sunt invocate pentru a explica posibilitatea diviziunilor suplimentare ale schițelor dentare, în contextul teoriei diviziunii mugurelui dentar?","options":[{"id":"A","text":"Proliferarea și invaginarea stratului tecii epiteliale a lui Hertwig."},{"id":"B","text":"O modificare a concentrațiilor substanțelor inductoare chimice."},{"id":"C","text":"Inducția biologică și variațiile de intensitate metabolică locală."},{"id":"D","text":"Variațiile numerice ale substanțelor cu rol potențial în energetica celulară, precum ARN și fosfataze alcaline."},{"id":"E","text":"Dezvoltarea mugurilor dentari care în mod normal ar trebui să se atrofieze."}],"correct":["C","D"],"pages":[455],"source":"set-2"},{"id":"set2-CnN4Iq8z","fingerprint":"e370c0402b4c8493","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care afirmație descrie corect o limitare a teoriei evaginării epiteliului adamantin?","options":[{"id":"A","text":"Nu aduce probe de necontestat pentru mecanismele propuse."},{"id":"B","text":"Este incapabilă să explice formarea mai multor dinți supranumerari."},{"id":"C","text":"Se bazează exclusiv pe evaginarea epiteliului adamantin intern."},{"id":"D","text":"Nu este susținută de localizarea frecventă a dinților supranumerari."},{"id":"E","text":"Nu poate explica apariția anomaliei „dens in dente”."}],"correct":["E"],"pages":[455],"source":"set-2"},{"id":"set2-UgP4Wsuz","fingerprint":"1bca5d356c01f431","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care teorie postulează că dinții supranumerari sunt produși de o lamă epitelială accesorie independentă, considerată un vestigiu filogenetic?","options":[{"id":"A","text":"Teoria evaginării epiteliului adamantin."},{"id":"B","text":"Teoria diviziunii mugurelui dentar."},{"id":"C","text":"Teoria mugurilor adamantini multipli."},{"id":"D","text":"Teoria hiperactivității lamei dentare."},{"id":"E","text":"Teoria inducției vasculare."}],"correct":["C"],"pages":[455],"source":"set-2"},{"id":"set2-hyrvzVDw","fingerprint":"b464050555e3bdaf","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Deși explică varietatea mare a dinților supranumerari, care este principala obiecție de natură histologică adusă teoriei mugurilor adamantini multipli?","options":[{"id":"A","text":"Structurile epiteliale rudimentare nu au capacitatea de a genera dinți."},{"id":"B","text":"Dinții prelacteali sunt prea diferiți structural pentru a susține teoria."},{"id":"C","text":"Nu s-au pus în evidență muguri în plus față de cei din dentiția temporară sau permanentă."},{"id":"D","text":"Studiile nu au putut demonstra existența unei linii a patru dentiții."},{"id":"E","text":"Lama epitelială accesorie nu corespunde „bandei glandulare” a reptilelor."}],"correct":["C"],"pages":[455],"source":"set-2"},{"id":"set2-PKkEayk2","fingerprint":"2afbd5c5bcf4e8c7","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Conform teoriei proliferării anormale a resturilor epiteliale, care dintre următoarele structuri sunt considerate surse posibile pentru dinții supranumerari?","options":[{"id":"A","text":"Papila dentară"},{"id":"B","text":"Organul adamantin"},{"id":"C","text":"Perlele lui Serres"},{"id":"D","text":"Resturile lui Malassez"},{"id":"E","text":"Gubernaculum dentis"}],"correct":["C","D","E"],"pages":[456],"source":"set-2"},{"id":"set2-Vxr02b0h","fingerprint":"9b88c4d586c24f8e","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este principalul motiv menționat pentru dificultatea de a studia caracterul ereditar al dinților supranumerari?","options":[{"id":"A","text":"Prezența mai frecventă a discordanței decât a concordanței la gemenii monozigoți."},{"id":"B","text":"Variațiile morfologice mari ale dinților supranumerari."},{"id":"C","text":"Complexitatea codificării genetice a anomaliilor dentare."},{"id":"D","text":"Extracția frecventă a dinților supranumerari."},{"id":"E","text":"Lipsa de interes a cercetătorilor pentru acest subiect."}],"correct":["D"],"pages":[456],"source":"set-2"},{"id":"set2-7UupqV0q","fingerprint":"bc3fd8160976e385","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Ce condiție minimă trebuie îndeplinită pentru a defini o formațiune ca fiind un dinte supranumerar?","options":[{"id":"A","text":"Prezența unui țesut conjunctiv pulpar bogat vascularizat."},{"id":"B","text":"Să fie dezvoltat ca o formațiune total independentă."},{"id":"C","text":"Să fie erupt pe arcada dentară și să fie funcțional."},{"id":"D","text":"Existența a cel puțin două țesuturi dure, smalț și dentină."},{"id":"E","text":"Existența unui singur țesut dur, cum ar fi perla de smalț."}],"correct":["D"],"pages":[456],"source":"set-2"},{"id":"set2-oMO0gxxS","fingerprint":"9d8181f53ad78e3a","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile dinților neonatali (dentiția predeciduală)?","options":[{"id":"A","text":"Sunt ferm ancorați în osul alveolar prin rădăcini scurte."},{"id":"B","text":"Histologic, prezintă un țesut conjunctiv pulpar foarte bogat vascularizat."},{"id":"C","text":"Apar de obicei în al doilea an de viață."},{"id":"D","text":"Sunt localizați mai frecvent la nivelul grupului incisiv inferior."},{"id":"E","text":"Sunt atașați la gingie."}],"correct":["B","D","E"],"pages":[456],"source":"set-2"},{"id":"set2-xJnvBd4F","fingerprint":"8c7256011c96af69","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Cum sunt evaluate rolurile luesului congenital și abuzului de tutun și alcool la genitori ca factori cauzali pentru dinții supranumerari?","options":[{"id":"A","text":"Ambele sunt considerate factori cauzali importanți, fiind intens studiate."},{"id":"B","text":"Abuzul de tutun și alcool este un factor confirmat, spre deosebire de luesul congenital."},{"id":"C","text":"Rolul luesului congenital este neconvingător, iar cel al abuzului de tutun și alcool la genitori rezistă și mai puțin discuției."},{"id":"D","text":"Luesul congenital este considerat un factor determinant, în timp ce abuzul de substanțe este neconvingător."},{"id":"E","text":"Aceste ipoteze au fost formulate recent și necesită studii suplimentare pentru confirmare."}],"correct":["C"],"pages":[456],"source":"set-2"},{"id":"set2-xP5rKZn2","fingerprint":"7ab8b8269bafe358","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Referitor la caracteristicile dinților supranumerari, care dintre următoarele afirmații este corectă?","options":[{"id":"A","text":"Apar exclusiv înaintea dentiției normale, formând dentiția predeciduală."},{"id":"B","text":"Modificările morfologice sunt de origine dismetabolică și pot fi legate de poziția lor pe arcadă."},{"id":"C","text":"Vascularizația și inervația lor sunt identice cu cele ale dinților normali, indiferent de funcționalitate."},{"id":"D","text":"Se dezvoltă întotdeauna independent, fără nicio legătură cu dinții din seria normală."},{"id":"E","text":"Din punct de vedere histologic, sunt considerați formațiuni odontoide, diferiți de dinții normali."}],"correct":["B"],"pages":[456],"source":"set-2"},{"id":"set2-BYH_-t4V","fingerprint":"6682b1970369ff25","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care sunt caracteristicile dinților neonatali propriu-ziși?","options":[{"id":"A","text":"Examenul histologic relevă un strat gros de smalț și o pulpă slab vascularizată."},{"id":"B","text":"Apar în primele luni de viață și sunt localizați frecvent în regiunea incisivilor inferiori."},{"id":"C","text":"Filogenetic, amintesc de dentiția mamiferelor evoluate."},{"id":"D","text":"Reprezintă o formă de dentiție postpermanentă."},{"id":"E","text":"Sunt atașați ferm de osul alveolar prin rădăcini bine dezvoltate."}],"correct":["B"],"pages":[457],"source":"set-2"},{"id":"set2-RCwPnB4v","fingerprint":"3726abf52f99d1df","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele semne clinice pot sugera prezența unui dinte supranumerar inclus format în același timp cu dentiția normală?","options":[{"id":"A","text":"Existența unei diasteme interincisive fără o cauză evidentă, după erupția caninilor."},{"id":"B","text":"Erupția precoce a incisivilor centrali permanenți."},{"id":"C","text":"Resorbția accelerată a crestelor alveolare în zona respectivă."},{"id":"D","text":"Prezența distopiilor generalizate la nivelul întregii arcade."},{"id":"E","text":"Persistența unuia sau mai multor dinți temporari peste vârsta obișnuită de permutare."}],"correct":["A","E"],"pages":[457],"source":"set-2"},{"id":"set2-AAXiLmFj","fingerprint":"08454cf4e4e6b326","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Ce definește un dinte anastrofic?","options":[{"id":"A","text":"Un dinte neonatal care persistă până la erupția dentiției permanente."},{"id":"B","text":"Un dinte supranumerar erupt, situat vestibular față de arcadă."},{"id":"C","text":"Un dinte supranumerar inclus, orientat cu coroana spre planul de ocluzie."},{"id":"D","text":"Un dinte supranumerar fuzionat cu un dinte din seria normală."},{"id":"E","text":"Un dinte supranumerar inclus, cu rădăcina orientată spre planul de ocluzie."}],"correct":["E"],"pages":[457],"source":"set-2"},{"id":"set2--vpJ6oxS","fingerprint":"7a876e75ce3c7884","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele sindroame polimalformative pot avea ca semn clinic prezența dinților supranumerari?","options":[{"id":"A","text":"Displazia oculo-mandibulo-facială (sindromul Hallermann-Streif-Francois)."},{"id":"B","text":"Sindromul Gardner."},{"id":"C","text":"Displazia cleido-craniană (sindromul Pierre Marie-Sainton)."},{"id":"D","text":"Sindromul Apert."},{"id":"E","text":"Sindromul Pierre Robin."}],"correct":["A","B","C"],"pages":[457],"source":"set-2"},{"id":"set2-yOWiEqy8","fingerprint":"9166545d769d86da","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Ce caracteristici sunt specifice meziodensului?","options":[{"id":"A","text":"Apare doar la maxilarul superior."},{"id":"B","text":"Este multicuspidat și multiradicular, asemănător unui molar."},{"id":"C","text":"Erupția sa urmează întotdeauna erupției caninului permanent."},{"id":"D","text":"Este întotdeauna un element multiplu, prezentând aspect de complex fuzional."},{"id":"E","text":"Poate provoca incluzia incisivilor centrali permanenți sau malpoziții ale acestora."}],"correct":["A","E"],"pages":[457],"source":"set-2"},{"id":"set2-Wo6k4Ijc","fingerprint":"edcdc36ced4da25e","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Referitor la momentul apariției dinților supranumerari, care afirmație este corectă?","options":[{"id":"A","text":"Dinții supranumerari care formează dentiția postpermanentă sunt exclusiv dinți formați după dentiția permanentă."},{"id":"B","text":"Dinții neonatali fac parte din dentiția normală, dar au o erupție accelerată."},{"id":"C","text":"Dentiția postpermanentă se referă la dinții supranumerari care erup între dentiția temporară și cea permanentă."},{"id":"D","text":"Dinții supranumerari care se formează odată cu dentiția normală erup întotdeauna pe arcadă."},{"id":"E","text":"Meziodensul erupe în jurul vârstei de 6-7 ani, ceea ce face ca apartenența sa la dentiția temporară sau permanentă să fie contradictorie."}],"correct":["E"],"pages":[457],"source":"set-2"},{"id":"set2-EHfcY9Ry","fingerprint":"157877a9618c6f53","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt caracteristicile generale ale dinților supranumerari?","options":[{"id":"A","text":"Au întotdeauna forme anatomice perfect definite, identice cu dinții normali."},{"id":"B","text":"Pot erupe sau pot rămâne incluși."},{"id":"C","text":"Sunt, de cele mai multe ori, atipici și de volum redus."},{"id":"D","text":"Prezența lor este întotdeauna un fenomen izolat, nefiind asociată cu alte afecțiuni."},{"id":"E","text":"Au o localizare exclusiv vestibulară față de linia normală a arcadei."}],"correct":["B","C"],"pages":[457],"source":"set-2"},{"id":"set2-jV2hZLxS","fingerprint":"ffa7b6a71f3f9643","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt afirmațiile corecte referitoare la utilizarea ortopantomogramei în diagnosticul dinților supranumerari?","options":[{"id":"A","text":"Este inferioară radiografiei retroalveolare pentru vizualizarea de ansamblu a anomaliei."},{"id":"B","text":"Este necesară și obligatorie pentru a aprecia numărul de elemente dentare în plus în ansamblul întregii dentiții."},{"id":"C","text":"Vizualizează cu cea mai mare precizie sediul vestibular sau oral al dinților incluși."},{"id":"D","text":"Meziodensul este întotdeauna vizualizat cu claritate, fără suprapuneri."},{"id":"E","text":"Poate genera confuzii de diagnostic în regiunea anterioară."}],"correct":["B","E"],"pages":[458],"source":"set-2"},{"id":"set2-DH6_pC6o","fingerprint":"12f3ecfbf0488c3b","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Ce metode radiologice sunt indicate pentru a preciza cu exactitate poziția intraosoasă, vestibulară sau orală, a unui dinte supranumerar inclus?","options":[{"id":"A","text":"Incidența endobucală axială cu film ocluzal"},{"id":"B","text":"Radiografia retroalveolară izometrică și ortoradială"},{"id":"C","text":"Ortopantomograma"},{"id":"D","text":"Radiografia excentrică"},{"id":"E","text":"Radiografia ocluzală"}],"correct":["A","D","E"],"pages":[458],"source":"set-2"},{"id":"set2-04MwFvqe","fingerprint":"8fad0bed82e99160","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"În cazul aplicării radiografiei excentrice (tehnica Clark), ce indică o poziție orală a dintelui inclus?","options":[{"id":"A","text":"Imaginea dintelui inclus se deplasează în același sens cu deplasarea conului de radiații."},{"id":"B","text":"Imaginea dintelui inclus se deplasează în sens invers față de deplasarea conului de radiații."},{"id":"C","text":"Se realizează o singură radiografie în incidență ortogonală."},{"id":"D","text":"Este obligatoriu ca ambele filme să fie realizate fără a însemna ordinea lor."},{"id":"E","text":"Elementele anatomice apropiate de film se deplasează în direcție opusă sursei de radiații."}],"correct":["A"],"pages":[458],"source":"set-2"},{"id":"set2-4Du9zz-a","fingerprint":"ba9bee1415bd6c29","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Ce elemente pot duce la interpretarea eronată a unui meziodens pe o ortopantomogramă?","options":[{"id":"A","text":"Suprapunerea meziodensului peste suprafața radiculară a unui incisiv central."},{"id":"B","text":"Umbrele oaselor nazale proiectate în apropierea liniei mediane."},{"id":"C","text":"Utilizarea unei radiografii retroalveolare suplimentare."},{"id":"D","text":"Prezența unei incluzii vestibulare a dintelui."},{"id":"E","text":"Proiecția liniei arcadei dentare."}],"correct":["B"],"pages":[458],"source":"set-2"},{"id":"set2-AQQFylr5","fingerprint":"5fd4ffe5027791c6","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"În ce situații este indicată utilizarea unei radiografii retroalveolare pentru a completa o ortopantomogramă în diagnosticul dinților supranumerari?","options":[{"id":"A","text":"Pentru vizualizarea în detaliu a particularităților dinților supranumerari în regiunea anterioară."},{"id":"B","text":"Pentru a confirma sau infirma o suspiciune de meziodens cauzată de umbrele oaselor nazale."},{"id":"C","text":"Când un meziodens se suprapune peste rădăcina unui incisiv central, îngreunând interpretarea."},{"id":"D","text":"Pentru a evalua numărul total de dinți supranumerari la nivelul ambelor arcade."},{"id":"E","text":"Pentru a stabili cu precizie sediul vestibular sau oral al unui dinte inclus."}],"correct":["B","C"],"pages":[458],"source":"set-2"},{"id":"set2-QxWt9NzS","fingerprint":"2fa227fb0c19bfa7","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care este atitudinea terapeutică de elecție în majoritatea cazurilor de dinți supranumerari și care este principalul criteriu de evaluare clinică?","options":[{"id":"A","text":"Evaluarea se face în funcție de consecințele cauzate la nivelul dinților din seria normală."},{"id":"B","text":"Tratamentul este identic pentru dinții erupți și cei incluși, fără a se ține cont de impactul lor."},{"id":"C","text":"Îndepărtarea chirurgicală (extracția) este metoda de elecție."},{"id":"D","text":"Principalul criteriu de evaluare este morfologia dintelui supranumerar."},{"id":"E","text":"Se preferă întotdeauna monitorizarea pe termen lung fără intervenție."}],"correct":["A","C"],"pages":[458],"source":"set-2"},{"id":"set2-aT5mvRtx","fingerprint":"953ff8d979c8f37c","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este succesiunea corectă a fazelor terapeutice în cazul unui dinte permanent inclus din cauza unui dinte supranumerar, atunci când spațiul pe arcadă este redus?","options":[{"id":"A","text":"Mărirea perimetrului arcadei, urmată de intervenția chirurgicală și apoi tracțiunea dintelui permanent."},{"id":"B","text":"Mărirea perimetrului arcadei, urmată direct de tracțiunea dintelui permanent, intervenția chirurgicală fiind opțională."},{"id":"C","text":"Extracția dintelui supranumerar, urmată de monitorizarea erupției spontane, fără a mai fi necesară mărirea arcadei sau tracțiunea."},{"id":"D","text":"Intervenția chirurgicală, urmată de mărirea perimetrului arcadei și apoi tracțiunea dintelui permanent."},{"id":"E","text":"Tracțiunea dintelui permanent, urmată de extracția dintelui supranumerar și, la final, mărirea perimetrului arcadei."}],"correct":["A"],"pages":[459],"source":"set-2"},{"id":"set2-J1mcM_cj","fingerprint":"c30fb8aea8d78ab6","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Ce tulburări pot fi determinate de dinții supranumerari erupți în afara arcadei dentare?","options":[{"id":"A","text":"Apariția diastemei interincisive."},{"id":"B","text":"Îmbunătățirea condițiilor de autocurățire prin stimularea fluxului salivar."},{"id":"C","text":"Blocaje ocluzo-articulare, în special în localizările orale la arcada superioară."},{"id":"D","text":"Prevenirea apariției cariilor la dinții adiacenți prin crearea de spații suplimentare."},{"id":"E","text":"Resorbții radiculare ale dinților din seria normală."}],"correct":["A","C","E"],"pages":[459],"source":"set-2"},{"id":"set2-JV3UxQmN","fingerprint":"63a7bc06eacb1235","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"În ce situație clinică nu este indicată extracția unui dinte supranumerar erupt?","options":[{"id":"A","text":"Când dintele supranumerar determină tulburări fizionomice majore."},{"id":"B","text":"Când este vorba de un al 5-lea incisiv inferior, aliniat pe arcadă, cu aspect și volum normale."},{"id":"C","text":"Când dintele supranumerar este inclus și nu influențează erupția dinților permanenți."},{"id":"D","text":"Când prezența sa a condus la malpoziții ale dinților permanenți adiacenți."},{"id":"E","text":"Când dintele supranumerar determină blocaje ocluzo-articulare în timpul mișcărilor mandibulare."}],"correct":["B"],"pages":[459],"source":"set-2"},{"id":"set2-2ng_LoR0","fingerprint":"c9e843803aeaf379","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este atitudinea terapeutică de elecție în majoritatea situațiilor care implică dinți supranumerari?","options":[{"id":"A","text":"Tratamentul endodontic al dintelui supranumerar pentru conservarea acestuia."},{"id":"B","text":"Tratamentul ortodontic pentru a alinia dintele supranumerar pe arcadă."},{"id":"C","text":"Monitorizarea pe termen lung, fără intervenție activă."},{"id":"D","text":"Aplicarea de sigilanți pentru a preveni caria dintelui supranumerar erupt."},{"id":"E","text":"Îndepărtarea chirurgicală (extracția)."}],"correct":["E"],"pages":[459],"source":"set-2"},{"id":"set2-qa1TRuPW","fingerprint":"6b5de19c89c94f79","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Ce abordare terapeutică este indicată atunci când un dinte supranumerar a cauzat incluzia unui dinte permanent, dar există spațiu suficient pe arcadă pentru erupția și alinierea acestuia?","options":[{"id":"A","text":"Tracțiunea ortodontică a dintelui permanent inclus, fără a extrage dintele supranumerar."},{"id":"B","text":"Expectativă armată, monitorizând posibilitatea erupției spontane a dintelui permanent."},{"id":"C","text":"Mărirea perimetrului arcadei alveolo-dentare ca primă etapă."},{"id":"D","text":"Extracția dintelui supranumerar pentru a facilita erupția dintelui permanent."},{"id":"E","text":"Aplicarea unui aparat ortodontic pentru a stimula \"neliniștea locală\" și erupția ambilor dinți."}],"correct":["D"],"pages":[459],"source":"set-2"},{"id":"set2-33eFSl3s","fingerprint":"b1ed65a1d1eebd5d","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"În ce situație clinică este considerată obligatorie extracția unui dinte supranumerar, chiar dacă acesta nu împiedică evoluția unui dinte permanent?","options":[{"id":"A","text":"Când este inclus și are o poziție favorabilă pentru evoluția ulterioară pe arcadă."},{"id":"B","text":"Atunci când se asociază cu microdenția dinților din seria normală."},{"id":"C","text":"Dacă dintele supranumerar este situat lângă un dinte din seria normală compromis."},{"id":"D","text":"În cazul dinților supranumerari anastrofici cu potențial de evoluție necontrolată."},{"id":"E","text":"Când dintele supranumerar este complet integrat estetic și funcțional pe arcadă."}],"correct":["D"],"pages":[460],"source":"set-2"},{"id":"set2-shS6B3R5","fingerprint":"cfbab050c5888705","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele situații reprezintă contraindicații pentru extracția unui dinte supranumerar?","options":[{"id":"A","text":"Dintele supranumerar este localizat în vecinătatea unui dinte din seria normală care este compromis și irecuperabil."},{"id":"B","text":"Dintele supranumerar este anastrofic și evoluează necontrolat spre sinusul maxilar."},{"id":"C","text":"Dintele supranumerar se asociază cu microdenția dinților din seria normală."},{"id":"D","text":"Dintele supranumerar împiedică alinierea corectă a dinților din seria normală."},{"id":"E","text":"Dintele supranumerar este de formă și dimensiune similară dinților permanenți și este complet integrat în arcadă."}],"correct":["A","C","E"],"pages":[460],"source":"set-2"},{"id":"set2-mVnclisZ","fingerprint":"b03e4d2a17db3c83","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"În contextul unui pacient cu un dinte permanent compromis, care nu poate fi păstrat pe arcadă, și un dinte supranumerar adiacent, care este atitudinea terapeutică adecvată?","options":[{"id":"A","text":"Aplicarea unor tehnici de adiție pe dintele supranumerar, fără a extrage dintele compromis."},{"id":"B","text":"Extracția dintelui irecuperabil din seria normală și alinierea dintelui supranumerar pe arcadă."},{"id":"C","text":"Păstrarea ambilor dinți și monitorizarea periodică a evoluției."},{"id":"D","text":"Extracția ambilor dinți, atât cel din seria normală, cât și cel supranumerar."},{"id":"E","text":"Extracția dintelui supranumerar pentru a facilita tratamentul protetic al dintelui compromis."}],"correct":["B"],"pages":[460],"source":"set-2"},{"id":"set2-S-2VM7LT","fingerprint":"859ccff535383f64","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care dintre următorii termeni definește un dinte supranumerar orientat cu coroana spre baza maxilarului și rădăcina spre planul de ocluzie?","options":[{"id":"A","text":"Paramolare"},{"id":"B","text":"Meziodens"},{"id":"C","text":"Dens in dente"},{"id":"D","text":"Distomolare"},{"id":"E","text":"Anastrofic"}],"correct":["E"],"pages":[453],"source":"set-2"},{"id":"set2-Os5_XWP1","fingerprint":"18092c8f7976ae0a","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la datele epidemiologice ale dinților supranumerari?","options":[{"id":"A","text":"Această anomalie are o incidență de două ori mai mare la persoanele de sex feminin comparativ cu cele de sex masculin."},{"id":"B","text":"Majoritatea pacienților afectați, în proporție de 60-75%, prezintă un singur dinte supranumerar."},{"id":"C","text":"Anomalia se regăsește cu predilecție pe maxilarul superior, în special în zona incisivilor superiori."},{"id":"D","text":"Dinții supranumerari se întâlnesc cu o frecvență de 9 ori mai mare în dentiția temporară față de cea permanentă."},{"id":"E","text":"Frecvența dinților supranumerari este cuprinsă între 1-5%."}],"correct":["B","C","E"],"pages":[453],"source":"set-2"},{"id":"set2-x5SPS4KZ","fingerprint":"a2fec35c101276cd","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt aspectele clinice pe care teoria atavică nu reușește să le explice în totalitate în ceea ce privește etiopatogenia dinților supranumerari?","options":[{"id":"A","text":"Apariția meziodensului ca fenomen de revenire la formule dentare anterioare."},{"id":"B","text":"Coexistența la același individ de dinți supranumerari pe o arcadă dentară cu anodonția pe arcada antagonistă."},{"id":"C","text":"Apariția caninilor supranumerari, din moment ce acest dinte nu apare multiplu în formula dentară primitivă."},{"id":"D","text":"Reducerea formulei incisive care s-a realizat dinainte-înapoi."},{"id":"E","text":"Frecvența diferită a dinților supranumerari pe cele două arcade dentare."}],"correct":["B","C","E"],"pages":[454],"source":"set-2"},{"id":"set2-3mvTEHHm","fingerprint":"7b7e821f70128aaa","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Conform teoriei celei de-a treia dentiții, care dintre următoarele elemente clinice servește ca argument de susținere a acestei ipoteze?","options":[{"id":"A","text":"Prezența dinților supranumerari situați vestibular în raport cu arcada dentară normală."},{"id":"B","text":"Apariția dinților supranumerari perfect aliniați în linia arcadei dentare."},{"id":"C","text":"Apariția mai frecventă a dinților supranumerari în poziție orală față de arcada dentară normală."},{"id":"D","text":"Gradul de calcifiere al dinților supranumerari similar cu cel al dinților din seria normală."},{"id":"E","text":"Prezența dinților supranumerari care însoțesc dentiția temporară."}],"correct":["C"],"pages":[454],"source":"set-2"},{"id":"set2-DYN8xx1J","fingerprint":"3d254f03bab6b65f","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt caracteristicile clinice și structurale ale dinților prelacteali?","options":[{"id":"A","text":"Au forma unui capușon de gingie prezent la naștere."},{"id":"B","text":"Sunt structuri keratinizate ușor de îndepărtat."},{"id":"C","text":"Prezintă o rădăcină scurtă, rudimentară."},{"id":"D","text":"Se exfoliază, în general, în cursul primelor săptămâni de viață."},{"id":"E","text":"Reprezintă dinți de lapte prezenți pe arcadă la naștere prin erupție precoce."}],"correct":["A","B","D"],"pages":[454],"source":"set-2"},{"id":"set2-QZZbdfce","fingerprint":"e23618a5e0f0af73","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care afirmație referitoare la argumentarea histologică a teoriei mugurilor adamantini multipli este valabilă?","options":[{"id":"A","text":"Histologia confirmă prezența constantă a unei lame epiteliale accesorii independente la nivelul gingiei neonatale."},{"id":"B","text":"Din punct de vedere histologic, nu s-a pus în evidență existența unor muguri în plus față de cei din dentițiile normale."},{"id":"C","text":"Examinarea microscopică evidențiază transformarea mugurilor rudimentari atrofiați direct în dinți de lapte."},{"id":"D","text":"Teoria este susținută de identificarea frecventă a mugurilor excedentari în secțiunile histologice ale lamei dentare temporare."},{"id":"E","text":"Secțiunile histologice demonstrează o structură radiculară complexă a dinților prelacteali."}],"correct":["B"],"pages":[455],"source":"set-2"},{"id":"set2-JUTzdJIV","fingerprint":"8c26d12088651105","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt afirmațiile adevărate privind mecanismul de apariție a dinților supranumerari prin prisma teoriei mugurilor adamantini multipli?","options":[{"id":"A","text":"Lipsa involuției mugurilor dentari suplimentari determină o dezvoltare fundamental diferită de cea a dinților normali."},{"id":"B","text":"Lama dentară generează în mod fiziologic o multitudine de muguri dentari, dintre care majoritatea se atrofiază."},{"id":"C","text":"Resturile epiteliale ale mugurilor rudimentari sunt obligatoriu sortite dispariției complete, fără excepție."},{"id":"D","text":"Un argument clinic pentru originea unor dinți supranumerari este dezvoltarea acestora cu mult înaintea dinților permanenți."},{"id":"E","text":"Forma și structura dinților supranumerari pot fi de multe ori normale datorită dezvoltării similare cu a dinților din seriile fiziologice."}],"correct":["B","D","E"],"pages":[454],"source":"set-2"},{"id":"set2-UaZZKzdj","fingerprint":"7d6ef051a2449769","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Cărei structuri i-ar corespunde lama epitelială accesorie independentă, implicată în generarea dinților prelacteali, conform unora dintre susținătorii teoriei mugurilor multipli?","options":[{"id":"A","text":"Bandei glandulare a reptilelor."},{"id":"B","text":"Lamei dentare primare a dentiției lacteale."},{"id":"C","text":"Structurilor keratinizate ale erupției precoce."},{"id":"D","text":"Capușonului de gingie specific mamiferelor inferioare."},{"id":"E","text":"Resturilor epiteliale ale dentiției postpermanente."}],"correct":["A"],"pages":[455],"source":"set-2"},{"id":"set2-w4njRgVe","fingerprint":"b16b937a51dc9aeb","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele dentiții sunt indicate ca linii filogenetice potențiale de existența mugurilor rudimentari, vizibili după dispariția lor sub formă de resturi epiteliale?","options":[{"id":"A","text":"Dentiția tranzițională."},{"id":"B","text":"Dentiția prelacteală."},{"id":"C","text":"Dentiția postpermanentă."},{"id":"D","text":"Dentiția permanentă."},{"id":"E","text":"Dentiția lacteală."}],"correct":["B","C","D","E"],"pages":[454],"source":"set-2"},{"id":"set2-Ns9ZBDEt","fingerprint":"07c6c1cd47e6c7fa","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt mecanismele etiopatogenice propuse pentru a explica teoria hiperactivității lamei dentare?","options":[{"id":"A","text":"O perturbare histochimică ce influențează activitatea normală a lamei dentare."},{"id":"B","text":"O inducție vasculară ce determină o hiperactivitate a lamei dentare."},{"id":"C","text":"Formarea accidentală a unui boboc epitelial supranumerar în perioada embrionară."},{"id":"D","text":"Supraproducția realizată pe seama lamei dentare mediale."},{"id":"E","text":"O modificare a concentrațiilor substanțelor inhibitoare ale organului smalțului."}],"correct":["A","B","C"],"pages":[455],"source":"set-2"},{"id":"set2-wi0oxryI","fingerprint":"26bd33dfcfb6a1a1","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este mecanismul prin care mugurii excedentari generați fiziologic de lama dentară pot deveni dinți supranumerari?","options":[{"id":"A","text":"Mugurii supranumerari fuzionează cu mugurii normali generând structuri dentare atipice."},{"id":"B","text":"Mugurii care în mod normal ar trebui să se atrofieze își definitivează dezvoltarea."},{"id":"C","text":"Lama dentară formează post-natal un nou set de muguri epiteliali cu ritm de creștere accelerat."},{"id":"D","text":"Materialul embrionar excedentar migrează în zona apexului dinților temporari."},{"id":"E","text":"Mugurii principali se divid printr-un proces de dihotomie coronară în perioada de clopot."}],"correct":["B"],"pages":[455],"source":"set-2"},{"id":"set2-YjGdUiuQ","fingerprint":"ab53ce172a7519e5","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care dintre următoarele afirmații privind teoria hiperactivității lamei dentare sunt adevărate?","options":[{"id":"A","text":"Teoria hiperactivității lamei dentare a fost inițial propusă de Kolhmann în anul 1868."},{"id":"B","text":"Supraproducția lamei dentare se realizează pe seama porțiunilor care în mod normal formează dinții temporari."},{"id":"C","text":"Dinții supranumerari rezultați din mugurii care ar trebui să se atrofieze capătă o structură și o formă normale."},{"id":"D","text":"Legea de dezvoltare a dinților câștigată în ontogeneză se transmite exact în cursul filogenezei."},{"id":"E","text":"Alterarea legăturilor radicalilor chimici ai substanțelor inductoare reprezintă un factor patogenic plauzibil."}],"correct":["A","C","E"],"pages":[455],"source":"set-2"},{"id":"set2-pulWKrvi","fingerprint":"19d977ba4423169b","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt caracteristicile teoriei diviziunii mugurelui dentar și ale formării dinților supranumerari?","options":[{"id":"A","text":"Formarea dinților se desfășoară sub coordonarea informației genetice prin inducție biologică."},{"id":"B","text":"Ipoteza existenței unui material embrionar strict limitat destinat fiecărui dinte este considerată pe deplin viabilă."},{"id":"C","text":"În majoritatea cazurilor, dinții supranumerari au un volum identic cu cel al dinților din seria normală."},{"id":"D","text":"Teoria postulează împărțirea unui mugure dentar din seria normală în două părți cu evoluție independentă."},{"id":"E","text":"Dinții rezultați din diviziunea aceluiași material embrionar ar trebui teoretic să fie micșorați de volum în mod uniform."}],"correct":["A","D","E"],"pages":[455],"source":"set-2"},{"id":"set2--OMjfya8","fingerprint":"7a2e655621e3ea67","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Ce substanțe evidențiate la nivelul organului adamantin, implicate în energetica celulară, pot determina diviziuni suplimentare ale schițelor dentare fără a altera odontogeneza normală?","options":[{"id":"A","text":"ARN-ul"},{"id":"B","text":"Mucopolizaharidele"},{"id":"C","text":"Fosfatazele alcaline"},{"id":"D","text":"Glicogenul"},{"id":"E","text":"Colagenul de tip I"}],"correct":["A","B","C","D"],"pages":[455],"source":"set-2"},{"id":"set2-eDolENXm","fingerprint":"057748b6f6e51e7a","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Cum se definește inducția biologică responsabilă de conducerea formării dinților sub coordonarea informației genetice?","options":[{"id":"A","text":"Prin variații de intensitate metabolică locală cu transfer de energie intercelulară."},{"id":"B","text":"Prin diminuarea treptată a concentrației de mucopolizaharide la nivelul papilei dentare."},{"id":"C","text":"Prin alterarea programată a odontogenezei normale pentru a permite transferul energetic."},{"id":"D","text":"Prin atragerea pasivă a materialului embrionar limitat către polul apical."},{"id":"E","text":"Prin diviziunea mecanică a mugurelui dentar cu suprimarea temporară a expresiei genetice."}],"correct":["A"],"pages":[455],"source":"set-2"},{"id":"set2-HtXfL9h4","fingerprint":"eb6e81fcdd63229c","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este anomalia dentară pe care teoria evaginării epiteliului adamantin nu o poate explica?","options":[{"id":"A","text":"Apariția dinților supranumerari de dimensiuni mai mici."},{"id":"B","text":"Formarea unuia sau mai multor dinți supranumerari de aspect normal."},{"id":"C","text":"Dezvoltarea dinților supranumerari localizați în regiunea incisivă."},{"id":"D","text":"Formarea anomaliilor prin invaginarea stratului tecii epiteliale a lui Hertwig."},{"id":"E","text":"Apariția lui „dens in dente”."}],"correct":["E"],"pages":[455],"source":"set-2"},{"id":"set2-fLT0r1g7","fingerprint":"796b8208ab30e5e3","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt sursele resturilor epiteliale paradentare implicate în generarea dinților supranumerari, prin prisma teoriei proliferării anormale și întârziate?","options":[{"id":"A","text":"Teaca epitelială a lui Hertwig (resturile lui Malassez)."},{"id":"B","text":"Pediculul ce leagă mugurele dentar de lama dentară (perlele lui Serres)."},{"id":"C","text":"Epiteliul adamantin extern urmat de cel intern."},{"id":"D","text":"Gubernaculum dentis."},{"id":"E","text":"Mugurele-mamă deciduu."}],"correct":["A","B","D"],"pages":[456],"source":"set-2"},{"id":"set2-OSgZN7Ph","fingerprint":"7e222e14d3030c27","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt afirmațiile adevărate privind teoria evaginării epiteliului adamantin în etiologia formațiunilor supranumerare?","options":[{"id":"A","text":"Presupune proliferarea și evaginarea epiteliului adamantin extern urmată imediat de cea a epiteliului adamantin intern."},{"id":"B","text":"Identifică etiologia dinților supranumerari prin proliferarea și invaginarea sau evaginarea stratului tecii epiteliale a lui Hertwig."},{"id":"C","text":"Are la bază cercetările școlii de stomatologie din Praga desfășurate pe o perioadă de peste trei decenii."},{"id":"D","text":"Susține că prelungirea evaginată rămâne permanent atașată de mugurele-mamă pe parcursul dezvoltării."},{"id":"E","text":"Explică apariția dinților supranumerari exclusiv prin invaginarea resturilor lui Malassez."}],"correct":["A","B","C"],"pages":[455],"source":"set-2"},{"id":"set2-vg2fI5q9","fingerprint":"cc060ef62ce4dbd4","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este paradoxul biologic neexplicat de teoria proliferării anormale și întârziate a resturilor epiteliale paradentare?","options":[{"id":"A","text":"Motivul pentru care formațiunile epiteliale dezvoltă dinți complet structurați, deși frecvent constituie suport pentru formarea tumorilor."},{"id":"B","text":"Mecanismul de detașare a prelungirii evaginate de la nivelul perlelor lui Serres."},{"id":"C","text":"Localizarea preferențială a formațiunilor supranumerare în regiunea molară."},{"id":"D","text":"Cauza pentru care epiteliul adamantin intern proliferează întotdeauna înaintea epiteliului adamantin extern."},{"id":"E","text":"Convingerea că celulele epiteliale care își au originea în gubernaculum dentis posedă calități biologice superioare restului lamei dentare."}],"correct":["A"],"pages":[456],"source":"set-2"},{"id":"set2-L3Ss3c6g","fingerprint":"0e490a59f73705b1","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la factorul ereditar în etiologia dinților supranumerari?","options":[{"id":"A","text":"Literatura de specialitate prezintă un consens unanim asupra rolului exclusiv și incontestabil al eredității."},{"id":"B","text":"Prezența anomaliei la mai mulți frați elucidează complet mecanismul și modul de acțiune ereditar."},{"id":"C","text":"La gemenii monozigoți, cazurile de concordanță a anomaliei depășesc numeric cazurile de discordanță."},{"id":"D","text":"Identificarea acelorași dinți supranumerari la gemenii monozigoți susține ipoteza determinării genetice a afecțiunii."},{"id":"E","text":"Observarea anomaliei la mai multe generații este împiedicată de extracția de rutină a dinților supranumerari."}],"correct":["D","E"],"pages":[456],"source":"set-2"},{"id":"set2-7Dqye20N","fingerprint":"dd7f8ddaef92f08d","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care dintre următoarele condiții a fost incriminată în etiologia dinților supranumerari sub influența unei perioade în care această patologie domina obsesiv gândirea medicală, rolul ei fiind considerat astăzi neconvingător?","options":[{"id":"A","text":"Abuzul de alcool la genitori."},{"id":"B","text":"Luesul congenital."},{"id":"C","text":"Consangvinitatea părinților."},{"id":"D","text":"Abuzul de tutun la genitori."},{"id":"E","text":"Infecțiile virale din primul trimestru de sarcină."}],"correct":["B"],"pages":[456],"source":"set-2"},{"id":"set2-RvxMF12t","fingerprint":"a89916ab81afb82a","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt dificultățile și particularitățile studierii caracterului ereditar al dinților supranumerari?","options":[{"id":"A","text":"Existența unui număr mai mare de cazuri de discordanță comparativ cu cele de concordanță la gemenii monozigoți."},{"id":"B","text":"Imposibilitatea obiectivă a identificării acestor dinți la descendenții direcți proveniți din aceiași genitori."},{"id":"C","text":"Extracția frecventă a acestor dinți, ceea ce împiedică observarea longitudinală a anomaliei de-a lungul mai multor generații."},{"id":"D","text":"Uniformitatea opiniilor în literatura de specialitate care plafonează direcțiile noi de cercetare."},{"id":"E","text":"Lipsa studiilor suficiente, care limitează înțelegerea mecanismului genetic implicat."}],"correct":["A","C","E"],"pages":[456],"source":"set-2"},{"id":"set2-hEQ5DdX4","fingerprint":"e105add23597af5c","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care dintre următoarele afirmații descriu corect particularitățile clinice și de dezvoltare ale dinților supranumerari?","options":[{"id":"A","text":"Pentru a defini o formațiune ca dinte supranumerar este suficientă prezența exclusivă a perlei de smalț, fără alte țesuturi dure asociate."},{"id":"B","text":"Dinții neonatali posedă rădăcini bine dezvoltate și sunt localizați cel mai frecvent la nivelul grupului incisiv superior."},{"id":"C","text":"Dinții supranumerari constituie formațiuni odontoide, având o structură histologică total diferită de cea a dinților normali."},{"id":"D","text":"Dezvoltarea dinților supranumerari are loc în mod obligatoriu doar după formarea dentiției normale."},{"id":"E","text":"Dinții anastrofici reprezintă dinți supranumerari incluși care sunt orientați cu coroana spre baza maxilarului și rădăcina spre planul de ocluzie."}],"correct":["E"],"pages":[457],"source":"set-2"},{"id":"set2-N5fF3ER2","fingerprint":"970d300de27e9d65","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Atenția asupra prezenței unor dinți supranumerari rămași incluși, care se dezvoltă concomitent cu dentiția normală, poate fi atrasă de următoarele semne clinice:","options":[{"id":"A","text":"Existența unor depresiuni profunde și atrofii severe la nivelul crestei alveolare."},{"id":"B","text":"Erupția prematură și accelerată a incisivilor centrali permanenți."},{"id":"C","text":"Persistența unuia sau mai multor dinți temporari peste vârsta obișnuită de permutare."},{"id":"D","text":"Existența unei diasteme interincisive fără o cauză evidentă, observabilă după erupția incisivului lateral și a caninilor."},{"id":"E","text":"Prezența distopiilor izolate pe arcada dentară."}],"correct":["C","D","E"],"pages":[457],"source":"set-2"},{"id":"set2-KkatDgGU","fingerprint":"4d2b7f025500b887","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt caracteristicile principale ale meziodensului?","options":[{"id":"A","text":"Are cel mai frecvent o coroană de formă conică, fiind un dinte unicuspidat și uniradicular."},{"id":"B","text":"Erupția sa este strict condiționată de și apare întotdeauna abia după erupția incisivului central permanent superior."},{"id":"C","text":"Se dezvoltă cu exactitate pe linia mediană interincisivă, fără a aparține vreuneia dintre hemiarcade."},{"id":"D","text":"Apare în mod exclusiv la nivelul maxilarului superior."},{"id":"E","text":"Poate determina incluzia incisivilor centrali permanenți sau apariția unor malpoziții ale acestora."}],"correct":["A","D","E"],"pages":[457],"source":"set-2"},{"id":"set2-LEyLjWem","fingerprint":"e6d49feebcf3a114","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"În contextul diagnosticului radiologic prin incidență excentrică (regula Clark), care enunț descrie corect interpretarea imaginilor pentru stabilirea poziției unui dinte inclus?","options":[{"id":"A","text":"Elementele anatomice situate în proximitatea tubului radiogen se deplasează pe filmul radiografic în aceeași direcție cu sursa de radiații."},{"id":"B","text":"Dacă pe al doilea film imaginea dintelui se deplasează în același sens cu deplasarea conului de radiații, incluzia este situată oral."},{"id":"C","text":"Dacă pe a doua radiografie imaginea dintelui se deplasează în sens invers față de direcția conului de radiații, incluzia este situată oral."},{"id":"D","text":"Elementele anatomice situate în imediata apropiere a filmului radiografic se deplasează pe imagine în direcție opusă deplasării sursei de radiații."},{"id":"E","text":"Principiul paralaxei se bazează pe efectuarea unei singure radiografii, dintr-o incidență oblică standardizată."}],"correct":["B"],"pages":[458],"source":"set-2"},{"id":"set2-bt1Y-OgO","fingerprint":"53444768d4fd0fe3","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Prezența dinților supranumerari se poate manifesta ca parte a unui sindrom polimalformativ. Care dintre următoarele sindroame se asociază cu această anomalie dentară?","options":[{"id":"A","text":"Sindromul Pierre Robin."},{"id":"B","text":"Sindromul Gardner."},{"id":"C","text":"Displazia cleido-craniană (sindromul Pierre Marie-Sainton)."},{"id":"D","text":"Sindromul Langdon-Down (trisomia 21)."},{"id":"E","text":"Displazia ectodermică anhidrotică."}],"correct":["B","C","D"],"pages":[457],"source":"set-2"},{"id":"set2-H6CcONim","fingerprint":"54e66832b13853f7","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"Care este succesiunea fazelor terapeutice în cazul în care un dinte supranumerar a determinat incluzia unui dinte permanent, iar spațiul necesar erupției acestuia din urmă este redus?","options":[{"id":"A","text":"Intervenția chirurgicală pentru descoperirea dintelui permanent, tracțiunea ortodontică și, în final, mărirea perimetrului arcadei alveolo-dentare."},{"id":"B","text":"Extracția dintelui supranumerar, urmată de mărirea perimetrului arcadei alveolo-dentare și tracțiunea ortodontică a dintelui permanent."},{"id":"C","text":"Mărirea perimetrului arcadei alveolo-dentare, intervenția chirurgicală pentru îndepărtarea dintelui supranumerar, urmată de tracțiunea dintelui permanent."},{"id":"D","text":"Mărirea perimetrului arcadei alveolo-dentare, tracțiunea dintelui permanent inclus și intervenția chirurgicală finală pentru îndepărtarea dintelui supranumerar."},{"id":"E","text":"Tracțiunea ortodontică a dintelui permanent, extracția dintelui supranumerar și ulterior mărirea perimetrului arcadei alveolo-dentare."}],"correct":["C"],"pages":[459],"source":"set-2"},{"id":"set2-xhnNbhVP","fingerprint":"c6c0675bdd90d676","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care sunt situațiile clinice în care extracția dinților supranumerari este contraindicată?","options":[{"id":"A","text":"Dinții supranumerari care provoacă resorbții radiculare ale dinților din seria normală ca urmare a evoluției lor intraosoase."},{"id":"B","text":"Dinții supranumerari asociați cu microdenția dinților din seria normală."},{"id":"C","text":"Dinții supranumerari anastrofici care prezintă o evoluție necontrolată către fosele nazale sau sinusurile maxilare."},{"id":"D","text":"Dinții supranumerari incluși care beneficiază de o poziție favorabilă și ar putea înlocui un dinte normal predispus la complicații."},{"id":"E","text":"Dinții supranumerari complet integrați estetic și funcțional pe arcada dentară, care au o formă și o dimensiune similare dinților permanenți."}],"correct":["B","D","E"],"pages":[460],"source":"set-2"},{"id":"set2-qcapkjec","fingerprint":"2d1993027f985540","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Dinții supranumerari erupți în afara arcadei dentare, deși nu influențează direct erupția dinților permanenți, determină o serie de tulburări. Care dintre următoarele manifestări se numără printre aceste tulburări?","options":[{"id":"A","text":"Înghesuiri dentare ce duc la înrăutățirea condițiilor de autocurățire, favorizând dezvoltarea cariilor și a inflamațiilor gingivale."},{"id":"B","text":"Resorbții radiculare ale dinților din seria normală, apărute ca o consecință a evoluției intraosoase a dinților supranumerari."},{"id":"C","text":"Deplasarea și rotația dinților din seria normală, ce pot fi însoțite de apariția diastemei interincisive."},{"id":"D","text":"Blocaje ocluzo-articulare, frecvente în special la localizările vestibulare de la nivelul arcadei inferioare."},{"id":"E","text":"Mărirea spontană a perimetrului arcadei alveolo-dentare sub efectul forțelor de masticație exercitate asupra dintelui atipic."}],"correct":["A","B","C"],"pages":[459],"source":"set-2"},{"id":"set2-eppQoDtL","fingerprint":"635d4279bc17ecc3","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CS","text":"În cazul unui dinte permanent inclus din cauza lipsei de spațiu și a unui obstacol reprezentat de un dinte supranumerar, dintele din seria normală își poate relua spontan erupția după obținerea spațiului pe arcadă. Care este principalul fenomen responsabil pentru această reluare a erupției, înainte de o eventuală intervenție chirurgicală profundă?","options":[{"id":"A","text":"Reducerea bruscă a densității osului alveolar ca răspuns la acțiunea mușchilor masticatori."},{"id":"B","text":"Erupția imediată accelerată a dintelui supranumerar, care tractează dintele din seria normală prin intermediul fibrelor ligamentului parodontal."},{"id":"C","text":"Translația anastrofică a dintelui supranumerar, eliberând mecanic culoarul de erupție al dintelui permanent."},{"id":"D","text":"„Neliniștea locală” provocată de aparatul ortodontic, care are ca efect stimularea erupției dentare."},{"id":"E","text":"Resorbția fiziologică a radăcinii dintelui supranumerar declanșată de expansiunea arcadei."}],"correct":["D"],"pages":[459],"source":"set-2"},{"id":"set2-DTTdYnV0","fingerprint":"6e3072f92ec89707","chapterId":"set-2","subchapterId":"set2-6.1.1","type":"CM","text":"Care este motivația principală pentru care extracția dinților supranumerari anastrofici este considerată obligatorie, deși aceștia pot să nu blocheze erupția niciunui dinte permanent?","options":[{"id":"A","text":"Tendința de a provoca blocaje ocluzo-articulare severe prin perforarea corticalei vestibulare superioare."},{"id":"B","text":"Riscul de a se dezvolta necontrolat în interiorul sinusurilor maxilare."},{"id":"C","text":"Pericolul erupției masive în afara arcadei dentare, ceea ce ar anula ireversibil spațiul de curățire interodentară."},{"id":"D","text":"Asocierea lor frecventă și inevitabilă cu instalarea microdenției dinților din seria normală."},{"id":"E","text":"Posibilitatea de a avea o evoluție necontrolată către fosele nazale."}],"correct":["B","E"],"pages":[460],"source":"set-2"}];
